<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; $u=Security::requireRole(['administrador','gerente','operador']); $msg=null; if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null); $d=['nome'=>trim($_POST['nome']??''),'documento'=>preg_replace('/\D/','',$_POST['documento']??''),'tipo_documento'=>strlen(preg_replace('/\D/','',$_POST['documento']??''))>11?'CNPJ':'CPF','email'=>filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)?:null,'telefone'=>trim($_POST['telefone']??''),'celular'=>trim($_POST['celular']??''),'cep'=>trim($_POST['cep']??''),'endereco'=>trim($_POST['endereco']??''),'numero'=>trim($_POST['numero']??''),'complemento'=>trim($_POST['complemento']??''),'bairro'=>trim($_POST['bairro']??''),'cidade'=>trim($_POST['cidade']??''),'estado'=>strtoupper(trim($_POST['estado']??''))]; if(strlen($d['documento'])<11){$msg='CPF/CNPJ inválido.';}else{$st=db()->prepare('SELECT id FROM clientes WHERE documento=?');$st->execute([$d['documento']]);if($st->fetch()){$msg='Documento já cadastrado.';}else{$st=db()->prepare('INSERT INTO clientes(nome,documento,tipo_documento,email,telefone,celular,cep,endereco,numero,complemento,bairro,cidade,estado) VALUES(:nome,:documento,:tipo_documento,:email,:telefone,:celular,:cep,:endereco,:numero,:complemento,:bairro,:cidade,:estado)');$st->execute($d);Audit::log('Cadastro de cliente','clientes',(int)db()->lastInsertId());$msg='Cliente cadastrado com sucesso.';}}}$q=trim($_GET['q']??'');$st=db()->prepare('SELECT * FROM clientes WHERE nome LIKE ? OR documento LIKE ? OR telefone LIKE ? ORDER BY id DESC');$x="%$q%";$st->execute([$x,$x,$x]);$clientes=$st->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clientes</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/app.css"></head><body><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><h1>Clientes</h1><a href="dashboard.php">Dashboard</a></div><?php if($msg):?><div class="alert alert-info"><?=Security::e($msg)?></div><?php endif;?><div class="card p-3 mb-4"><h5>Novo cliente</h5><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-4"><input class="form-control" name="nome" placeholder="Nome" required></div><div class="col-md-3"><input class="form-control" name="documento" placeholder="CPF/CNPJ" required></div><div class="col-md-3"><input class="form-control" type="email" name="email" placeholder="E-mail"></div><div class="col-md-2"><input class="form-control" name="telefone" placeholder="Telefone"></div><div class="col-12"><input class="form-control" name="endereco" placeholder="Endereço completo"></div><div class="col-md-2"><input class="form-control" name="numero" placeholder="Número"></div><div class="col-md-3"><input class="form-control" name="bairro" placeholder="Bairro"></div><div class="col-md-3"><input class="form-control" name="cidade" placeholder="Cidade"></div><div class="col-md-1"><input class="form-control" name="estado" maxlength="2" placeholder="UF"></div><div class="col-md-2"><input class="form-control" name="cep" placeholder="CEP"></div><div class="col-md-1"><button class="btn btn-primary w-100">Salvar</button></div></form></div><form class="input-group mb-3"><input class="form-control" name="q" value="<?=Security::e($q)?>" placeholder="Buscar por nome, documento ou telefone"><button class="btn btn-outline-secondary">Buscar</button></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Nome</th><th>Documento</th><th>E-mail</th><th>Telefone</th><th>Cidade</th></tr></thead><tbody><?php foreach($clientes as $c):?><tr><td><?=Security::e($c['nome'])?></td><td><?=Security::e($c['documento'])?></td><td><?=Security::e($c['email'])?></td><td><?=Security::e($c['telefone'])?></td><td><?=Security::e($c['cidade'])?>/<?=Security::e($c['estado'])?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
